TITLE = "พาหิรทุกขสูตร"
SUB = "สังยุตตนิกาย สฬายตนวรรค (SN 35.5) · อายตนะภายนอก ๖ เป็นทุกข์ เป็นอนัตตา"
EXPAND = {
    "sn35.5:1.4": "Saddā dukkhā.\n" + "Yaṁ dukkhaṁ tadanattā.\nYadanattā taṁ ‘netaṁ mama, nesohamasmi, na meso attā’ti evametaṁ yathābhūtaṁ sammappaññāya daṭṭhabbaṁ.",
    "sn35.5:1.5": "gandhā dukkhā.\n" + "Yaṁ dukkhaṁ tadanattā.\nYadanattā taṁ ‘netaṁ mama, nesohamasmi, na meso attā’ti evametaṁ yathābhūtaṁ sammappaññāya daṭṭhabbaṁ.",
    "sn35.5:1.6": "rasā dukkhā.\n" + "Yaṁ dukkhaṁ tadanattā.\nYadanattā taṁ ‘netaṁ mama, nesohamasmi, na meso attā’ti evametaṁ yathābhūtaṁ sammappaññāya daṭṭhabbaṁ.",
    "sn35.5:1.7": "phoṭṭhabbā dukkhā.\n" + "Yaṁ dukkhaṁ tadanattā.\nYadanattā taṁ ‘netaṁ mama, nesohamasmi, na meso attā’ti evametaṁ yathābhūtaṁ sammappaññāya daṭṭhabbaṁ.",
    "sn35.5:1.11": "Evaṁ passaṁ, bhikkhave, sutavā ariyasāvako rūpesupi nibbindati, saddesupi nibbindati, gandhesupi nibbindati, rasesupi nibbindati, phoṭṭhabbesupi nibbindati, dhammesupi nibbindati.\nNibbindaṁ virajjati; virāgā vimuccati; vimuttasmiṁ vimuttamiti ñāṇaṁ hoti.\n‘Khīṇā jāti, vusitaṁ brahmacariyaṁ, kataṁ karaṇīyaṁ, nāparaṁ itthattāyā’ti pajānātī”ti.",
}
TH = {
    "1": "ภิกษุทั้งหลาย รูป (สิ่งที่ตาเห็น) เป็นทุกข์ สิ่งใดเป็นทุกข์ สิ่งนั้นเป็นอนัตตา (ไม่ใช่ตัวตน) "
         "สิ่งใดเป็นอนัตตา สิ่งนั้นควรเห็นด้วยปัญญาที่ถูกต้องตามความเป็นจริงว่า นั่นไม่ใช่ของเรา เราไม่ได้เป็นนั่น "
         "นั่นไม่ใช่ตัวตนของเรา เสียง กลิ่น รส สิ่งที่กายสัมผัส และธรรมารมณ์ (สิ่งที่ใจรู้) ก็เป็นทุกข์ เป็นอนัตตา "
         "ควรเห็นด้วยปัญญาเช่นเดียวกัน ภิกษุทั้งหลาย อริยสาวกผู้ได้ฟังแล้ว เห็นอยู่อย่างนี้ "
         "ย่อมเบื่อหน่ายในรูป ในเสียง ในกลิ่น ในรส ในโผฏฐัพพะ และในธรรมารมณ์ เมื่อเบื่อหน่ายก็คลายกำหนัด "
         "เพราะคลายกำหนัดจึงหลุดพ้น เมื่อหลุดพ้นแล้วก็รู้ว่าหลุดพ้นแล้ว รู้ชัดว่า การเกิดสิ้นแล้ว "
         "พรหมจรรย์อยู่จบแล้ว สิ่งที่ควรทำได้ทำเสร็จแล้ว ไม่มีอะไรต้องทำเพื่อความเป็นอย่างนี้อีก (จบสูตรที่ ๕)",
}
